create table fashion_products
(Product_id int,
product_name varchar(40),
 brand_id int,
 category_id int, 
 size varchar(30),
 color varchar(40),
 gender_category varchar(30),
 season varchar(40), 
 purchase_price float,
  selling_price float,
  stock_quantity int,
  discount_percentage float,
 launch_date date,
 material varchar(40),
 product_status  bit)
select * from fashion_products





# Display all fashion products
select * from fashion_products

#Find products with discounts above 20%
select * from fashion_products
where discount_percentage >20
